执行如下代码，会输出 `钢琴: 叮咚叮咚` 和 `吉他: 咚咚当当` 。这体现了面向对象编程的（　）特性。
class Instrument {
public:
    virtual void play() { cout << "乐器在演奏声音" << endl; }
    virtual ~Instrument() {}
};
class Piano : public Instrument {
public:
    void play() override { cout << "钢琴: 叮咚叮咚" << endl; }
};
class Guitar : public Instrument {
public:
    void play() override { cout << "吉他: 咚咚当当" << endl; }
};
// main 中 Instrument* instruments[2] 分别指向 Piano 与 Guitar，循环调用 play()

以下函数 `check()` 用于判断一棵二叉树是否为（　）。
bool check(TreeNode* root) {
    if (!root) return true;
    queue<TreeNode*> q;
    q.push(root);
    bool hasNull = false;
    while (!q.empty()) {
        TreeNode* cur = q.front(); q.pop();
        if (!cur) { hasNull = true; }
        else {
            if (hasNull) return false;
            q.push(cur->left);
            q.push(cur->right);
        }
    }
    return true;
}

